      var g = begin(st), ctx = g.ctx, P = g.P, f = state.row * 2, v = state.v;
      var c = CLIPS[v], kp = kpts(c, state.row), box = boxPose(CLIPS.orig, state.row), pel = kpts(CLIPS.orig, state.row)[KI.Pelvis];
      /* 左：侧视（与贴图同一套相机） */
      var W = narrow ? g.w : Math.min(g.w * 0.42, 300), cam = { yaw: -1.0, pitch: 0.12, s: 170, ox: W * 0.5, oy: 270, cx: pel[0], cy: pel[1] };
      line(ctx, [[10, 270], [W - 10, 270]], P.border, 1.5);
      var C = boxCorners(box).map(function (p) { return project(p, cam); });
      BOX_EDGES.forEach(function (e) { line(ctx, [C[e[0]], C[e[1]]], P.warn, 1.6); });
      var K2 = kp.map(function (p) { return project(p, cam); });
      BONES.forEach(function (b) { line(ctx, [K2[KI[b[0]]], K2[KI[b[1]]]], v === 'orig' ? P.good : P.bad, 2.4); });
      K2.forEach(function (q) { dot(ctx, q[0], q[1], 3, P.text); });
      text(ctx, 'G1 关键点（侧视，跟着骨盆）', 12, 16, P.muted, 'left');
      /* 右：两条曲线 */
      var pen = PEN[v], sl = SLIDE[v];
      var x0 = narrow ? 50 : W + 50, pw = g.w - x0 - 16, yOff = narrow ? 310 : 0;
