      text(ctx, '红：与箱子　橙：与地面', x0 + 4, yOff + 12, P.muted, 'left');
      var p2 = plot({ w: g.w, h: yOff + 300 }, { l: x0, r: 16, t: yOff + 170, b: 22 }, [0, T_FRAMES - 1], [0, 35]);
